package org.jsoup.nodes;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class TextNodeTest {

    @Mock
    private Appendable accum;

    @Mock
    private Document.OutputSettings out;

    @Test
    public void createFromEncoded_TextNotNull() {
        when(Document.create().outputSettings()).thenReturn(out);
        when(accum.append(anyString())).thenReturn(this.accum);
        TextNode textNode = TextNode.createFromEncoded("test");
        assertNotNull(textNode);
    }

    @Test
    public void text_ThrowsIOExceptionWhenOffsetIsNegative() {
        TextNode textNode = new TextNode("");
        when(accum.append(anyString())).thenReturn(this.accum);
        assertThrows(IOException.class, () -> textNode.text(-1));
    }

    @Test
    public void text_TextReturnsText() {
        String expectedText = "test";
        when(accum.append(expectedText)).thenReturn(this.accum);
        TextNode textNode = new TextNode("");
        assertEquals(expectedText, textNode.text());
    }

    @Test
    public void splitText_SplitTextDoesNotChangeLength() {
        TextNode textNode = new TextNode("test");
        StringBuilder expected = new StringBuilder("te");
        when(accum.append(expected)).thenReturn(this.accum);
        when(accum.append(anyString())).thenReturn(this.accum);
        when(out.depth()).thenReturn(1);
        textNode.splitText(1);
        assertEquals(0, textNode.text().length());
    }

    @Test
    public void splitText_SplitTextDoesNotTruncateWholeText() {
        TextNode textNode = new TextNode("test");
        StringBuilder expected = new StringBuilder("te");
        when(accum.append(expected)).thenReturn(this.accum);
        when(accum.append(anyString())).thenReturn(this.accum);
        when(out.depth()).thenReturn(1);
        textNode.splitText(2);
        assertEquals("test", textNode.text());
    }

    @Test
    public void isBlank_WithLeadingWhitespace_ReturnsFalse() {
        TextNode textNode = new TextNode(" ");
        assertFalse(textNode.isBlank());
    }

    @Test
    public void isBlank_WithoutWhitespace_ReturnsTrue() {
        TextNode textNode = new TextNode("");
        assertTrue(textNode.isBlank());
    }
}
